const values = [
            null,
            undefined,
            0,
            -0,
            123n,
            'hello world 😎',
            { b: 2, a: 1 },
            [1, 2n, 'a', { k: 1 }],
            new Set([3, 1, 2]),
            new Map([
                ['b', 2],
